import json
import re
import pandas as pd


def task_func(json_str):
    """
    Load a JSON string into a dictionary, double numerical values, and return
    a one-row pandas DataFrame built from the normalized dictionary.

    Rules:
    - Empty/invalid JSON -> empty DataFrame
    - Only top-level dictionaries are supported
    - Numeric scalars are doubled and stored as floats
    - Numeric strings are detected with regex, converted to float, doubled
    - Lists are processed element-wise
    - Nested dictionaries are left unchanged
    """

    numeric_pattern = re.compile(
        r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$"
    )

    def is_numeric_string(value):
        return isinstance(value, str) and bool(numeric_pattern.fullmatch(value.strip()))

    def normalize_value(value):
        if isinstance(value, bool):
            return value

        if isinstance(value, (int, float)):
            return float(value) * 2.0

        if is_numeric_string(value):
            return float(value.strip()) * 2.0

        if isinstance(value, list):
            return [normalize_value(item) for item in value]

        if isinstance(value, tuple):
            return tuple(normalize_value(item) for item in value)

        if isinstance(value, dict):
            return value

        return value

    if not isinstance(json_str, str) or not json_str.strip():
        return pd.DataFrame()

    try:
        data = json.loads(json_str)
    except (json.JSONDecodeError, TypeError, ValueError):
        return pd.DataFrame()

    if not isinstance(data, dict) or not data:
        return pd.DataFrame()

    normalized = {key: normalize_value(value) for key, value in data.items()}
    return pd.DataFrame([normalized])
